INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "え？　ランドソルの壁を……\nぐるっと一周？", 1, 112, 0, 11, 112039, 106431);
