INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ああ……美しい……\n美しい以外にこれを\n表現する言葉が見当たらないよ。", 1, 1212, 0, 11, 1212009, 100811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 1212, "", 91, 1212010, 0);
