INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "えへへ、きちんと上手に描けました。\n黙々と作業するのは嫌いじゃないです。\nでも……私なんかの絵で本当に\n喜んでもらえるんですかね？", 1, 2612, 0, 11, 2612009, 104011);
