INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "オラァ！　これでどうだ！\nよし、いい感じに\n仕上がったんじゃないか？", 1, 3912, 0, 11, 3912009, 106511);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 3912, "", 91, 3912010, 0);
