INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "しっかし、壁に絵を描くなんて\n思い切ったことをするもんだね。\n楽しかったし、街のために働くってのも\nたまになら悪くないからいいけどさ。", 1, 3912, 0, 11, 3912012, 106511);
