INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "このっ、このやろっ！\nここをこうしてフィニ～ッシュ！\nふぅ。ボスへの怒り……じゃなくて\n街への想いを込めた傑作ができたです。", 1, 4012, 0, 11, 4012009, 106611);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 4012, "", 91, 4012010, 0);
