INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "これも立派な下克上への道。\nバレない所から少しずつ……って！\nあそこに居るのはボス！？\nこうしちゃいられない！　逃げるです！", 1, 4012, 0, 11, 4012012, 106611);
