INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "牧場の仕事で柵を塗ったりすっけど、\n絵を描くってのはなかなかねぇから\n苦労したべ。", 1, 4112, 0, 11, 4112009, 103311);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 4112, "", 91, 4112010, 0);
