INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "その割にはよく描けたと思うけんど……\nどうだべ？　牧場に来てくれる人たちが\nこの絵を見てほっこりしてくれると\nうれしいなぁ。", 1, 4112, 0, 11, 4112012, 103311);
