INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "と～～ってもかわいい絵が描けたわ♪\n城壁にこんな絵が描いてあれば、\nランドソルが素敵な場所って\n伝わるわよね♪", 1, 4212, 0, 11, 4212012, 105211);
