INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ゆっくり、時間をかけちゃいましたけど\nこれで完成、です。\nふふっ、絵を描くのって楽しいですね。", 1, 4312, 0, 11, 4312009, 103811);
