INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふぅ。今日のお絵かき終了です。\n今日もいい感じに描けました！\nやばいですね☆", 1, 4512, 0, 11, 4512022, 105811);
