INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はぁ～っ、疲れたぁ……\nでも、苦労したぶん\nいい仕上がりになったんじゃない？\nそれなりに楽しかったし。", 1, 4512, 0, 11, 4512027, 106011);
