INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そうね、とっても楽しかったわ！\n時間を忘れて熱中しちゃったもの。", 1, 4512, 0, 11, 4512032, 106411);
