INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うん、いい感じに描けたね！\n……でもこの絵って、ずっと\nランドソルに残るんだよね？\nそ、それはちょっと恥ずかしいかも……", 1, 5012, 0, 11, 5012018, 100211);
