INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はぁ、何度見ても美しいね……\n絵を描くボクと、ボクが描いた絵で\n美しさを引き立てあってるよ。", 1, 5712, 0, 11, 5712009, 100811);
