INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "上手に出来たかな？\n練習の成果が出てるといいけど……\nあの、私の絵、どうですか？", 1, 6712, 0, 11, 6712009, 103611);
