INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふ、こうしてみなさまと一緒に\n絵を描くというのもまた\n楽しいものでございますね。", 1, 8612, 0, 11, 8612022, 105911);
