INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そうね。慣れないせいもあって\n緊張しちゃうけど、\nコッコロさんやみんなが一緒だと\n落ち着いて、楽しくやれる気がするわ。", 1, 8612, 0, 11, 8612027, 106411);
