INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "う～ん……最近少し絵柄が\n変わってきた気がするわね？\nなんだか【美食殿】のみんなに\n影響されてるような……？", 1, 8812, 0, 11, 8812009, 106011);
