INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふぅ、出来たわね。\nついつい夢中になっちゃったわ。\n子どもたちが一生懸命描く姿に\n影響されちゃったみたいね。", 1, 9312, 0, 11, 9312009, 102811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 9312, "", 91, 9312010, 0);
