INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふっ、こうやって大人も子どもも\n関係なく、みんなでひとつの仕事を\n成し遂げるっていうのも、\nなかなか気持ちいいものね。", 1, 9312, 0, 11, 9312012, 102811);
