INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "や、やりました……！\n今日はドジをせずに\n完成させることができましたよ！", 1, 9412, 0, 11, 9412009, 102511);
