INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふっ、こうやって絵を描くのも\n慣れてきたものです♪\n落ち着いて、ドジもしないで\n完成させられるようになってきました。", 1, 11312, 0, 11, 11312009, 102511);
