INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はは、そりゃ助かった。\nお前さん、物言いは突飛だが、\nそういうところにはよく気が回るねえ。\nいい子じゃないか。", 1, 14112, 0, 11, 14112045, 105611);
