INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うちもこの間、それやってしもうたなぁ。\nふふ、でも安心しておくれやす。\nきれいに落とす方法、\nうちが教えてあげますえ。", 1, 14312, 0, 11, 14312032, 101011);
