INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふ、帰ったらみんなで\nお風呂に入らないといけないね。\n……私も少し服を汚してしまった。\n自分がキャンバスになった気分だよ。", 1, 14312, 0, 11, 14312037, 101411);
