INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "あらあら、私の正確無比な\n筆致も捨てたものじゃないわよ？\n伊達に毎日メスを握ってる\nわけじゃないんだから♪", 1, 14712, 0, 11, 14712041, 105111);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 14712, "", 91, 14712042, 0);
