INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はは、アタシの筆さばきだって\nなかなか様になってたろう？\n……それで？　お前さんは\n誰の絵が一番だと思うんだい？", 1, 14712, 0, 11, 14712046, 105611);
