INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふー、やれやれ。\n久々に集中して肩が凝った。\nま、そのかいあっていいものが\nできたんじゃないかな？", 1, 15212, 0, 11, 15212009, 106811);
