INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ううん、ええ出来栄えやわぁ～\nやっぱり色塗りは尻尾でしたほうが、\n味のある色合いになりますなぁ。\n不思議なもんやわぁ♪", 1, 15512, 0, 11, 15512009, 101011);
