INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "歌って踊って絵を描いて～♪\nふふ、踊りながら、鼻歌交じりでも\n描けるようになったさ～♪", 1, 15712, 0, 11, 15712009, 101711);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 15712, "", 91, 15712010, 0);
