INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "って、わぁっ！　いつの間にか\n人だかりが……！\nそれなら絵を見てくれたお礼に、\nもうひと踊りするさ～♪", 1, 15712, 0, 11, 15712012, 101711);
