INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うん、これで完璧……おっと。\nもうこんな時間か。\nいやはや絵を描くというのは、\n突き詰めだすとキリがないね。", 1, 15812, 0, 11, 15812009, 101411);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 15812, "", 91, 15812010, 0);
