INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "つい時間を忘れて没頭してしまう……\nしかし推理小説を読み解くようで、\n悪くない気分だ。次はもっと早く\n最適解を見つけ出してみせるよ♪", 1, 15812, 0, 11, 15812012, 101411);
