INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よし、今度も素晴らしい完成度だ！\n役割分担をしたら、飛躍的に\n描くのが早くなったな！", 1, 16412, 0, 11, 16412025, 105311);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 16412, "", 91, 16412026, 0);
