INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "絵の下書きはボクに任せて。\nすべての美しさの源になる存在……\nそれがボクだからね！", 1, 16412, 0, 11, 16412035, 100811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 16412, "", 91, 16412036, 0);
