INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "それをクウカがなぞって……\nはぁっ、もし皆さんの作業を\n台無しにしちゃったらって思うと……\nす、すごく……興奮しますぅ……！", 1, 16412, 0, 11, 16412040, 104511);
