INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0.2, "", "", 1, "wac_talk_surprise_loop_shy", "", 16612, "", 3, 16612039, 105111);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 0, "", 0, "vo_wac_220730_003", "", 16612, "", 21, 16612040, "vo_wac_220730");
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "まったくもう……\nみんなして絵の具まみれじゃない。\nって、あら？　この赤いのは……", 1, 16612, 0, 11, 16612041, 105111);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 16612, "", 91, 16612042, 0);
