INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふぇっ、私の絵の評判がいい！？\n後ろで見てた人に褒められてた？\nそ、そんな、私の絵なんて……\nもちろん真面目に描きましたけど……", 1, 16712, 0, 11, 16712013, 105511);
