INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よぉし、文句なしの出来栄えだ！\nしかし【カルミナ】はさておき、\n【王宮騎士団（NIGHTMARE）】\nまで引き続きお絵描きとはな。", 1, 16912, 0, 11, 16912009, 107111);
