INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "だが翻せばこれは、ぼくの芸術が\n人心を揺るがすと懼れられた証左だ。\nすなわち、ぼくは否定されることで\nかえって肯定されたのだよ。ふはは。", 1, 17312, 0, 11, 17312013, 111011);
