INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0.2, "wac_talk_smile_loop", "", 0, "wac_talk_smile_in", 1, 17812, "", 3, 17812030, 100511);
