INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "まったく、分かっていないな！\n芸術とは感性の爆発だ、勢い任せだ！\n宴の始まりに狂喜乱舞するかの如く、\n本能のまま描くのが最良なんだぞ☆", 1, 17812, 0, 11, 17812037, 107111);
