INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "さて、こんなもんか。\nだんだん慣れてきたけど、\nやっぱり剣を振るのとは、\nだいぶ勝手が違うね。", 1, 18412, 0, 11, 18412009, 105611);
