INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "お姉ちゃんのお姉ちゃんによる、\nお姉ちゃん史を覆す芸術が完成したよ！\n弟くんも一目見ただけで、この絵から\nお姉ちゃんを感じてくれるよね？", 1, 19112, 0, 11, 19112009, 104911);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 19112, "", 91, 19112010, 0);
