INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "この調子でどんどん絵を練習して、\n弟くんへの愛情を表現していかないと。\nまずは弟くんに膝枕してるお姉ちゃんの\n絵で、ランドソルを包囲しようかな♪", 1, 19112, 0, 11, 19112012, 104911);
