INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よし、できあがりだ！\n畑違いな依頼の気もするが、\n軍人たるもの、どんな任務でも\n忠実にこなさなければな。", 1, 19712, 0, 11, 19712009, 105311);
