INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ええっと、このあとは……\n薬草集めに、倉庫整理か。\nや、やっぱり、もう少し軍人らしい\n依頼を率先して受けるべきか？", 1, 19712, 0, 11, 19712013, 105311);
