INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うん。いい感じ。\n絵を描くなんてできるかしらって\n思っていたけれど、慣れてくると\nどんどん楽しくなってきたわ♪", 1, 20112, 0, 11, 20112009, 106411);
