INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "私が【美食殿】のみんなを\n描いてみるのもいいかも。\nみんな、喜んでくれるかしら。\nきっと喜んでくれるわよね。", 1, 20112, 0, 11, 20112012, 106411);
