INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "しかし、不思議でございますね。\nこの壁の絵は一人が描いたのではなく、\n大勢の方々が協力して\n作り上げているものです。", 1, 20212, 0, 11, 20212009, 105911);
