INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "それでもきれいに、\nひとつの作品に仕上がっていく……\nみなさまが、お互いを信頼しているから\n実現できた事業なのでしょう♪", 1, 20212, 0, 11, 20212012, 105911);
