INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "なんとか、できあがりました。\n大きな絵を描くのは、\nライブで体を動かすのとは、\nまた違った大変さがありますね……", 1, 20612, 0, 11, 20612009, 104211);
