INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "でも、だからこそ達成感も大きいです。\nライブも、絵も、見る人に喜びを\n与えられる……これからもぜひ、\nお手伝いしていきたいですね♪", 1, 20612, 0, 11, 20612012, 104211);
