INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふぃ～、やっと終わったです。\n絵を描くのは嫌いじゃねーですけど、\nボスはなんでもかんでもあたしらに\n仕事を押しつけすぎでは……", 1, 20712, 0, 11, 20712009, 106611);
