INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "あたしが下剋上した暁には、\n雑巾がけから夕飯の買い物まで、\nぜ～んぶボスに押しつけてやるです！\nいつになるかは分からねーですけど！", 1, 20712, 0, 11, 20712013, 106611);
