INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うん、よくできたかな？\nこうして絵を描いていると\n気分が落ち着くな～\nやっぱり、好きなことだから。", 1, 20912, 0, 11, 20912009, 106711);
