INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "君はどうかな？　絵は好き？\n好きだったら嬉しいかな～？\n興味のある人と同じ趣味だったら、\n素敵だなって思うでしょ♪", 1, 20912, 0, 11, 20912012, 106711);
