INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うち、見ちゃったんだよね……\nこないだ学校でユニ先輩が、\nもう一人のユニ先輩に筆を持たせて\n何やら教えこんでるカンジの場面……", 1, 21212, 0, 11, 21212009, 110811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 21212, "", 91, 21212010, 0);
