INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "なんか自動描画プログラム？\nとかいうのが調整ダルくて\n諦めたッつってたけど。\n何させるつもりだったんだ、あの人……", 1, 21212, 0, 11, 21212012, 110811);
