INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はっ、そうです！\nこの調子で、ぼっちでも関係ない\n趣味を発掘しまくれば、ぼっちライフも\n充実していくのでは……！？", 1, 21412, 0, 11, 21412012, 104011);
