INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よし、これは会心のデキです！\nどうですか騎士さん、\nどこを見ても文句のつけどころが\nないとは思いませんか？", 1, 22412, 0, 11, 22412009, 105411);
