INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "でもそれだと臨場感に欠けるから、\n絵にあわせて壁を殴って、凹凸を\nつけられねーかなって思ったんだけど。\nやっぱダメか、怒られそうだな。", 1, 22612, 0, 11, 22612012, 106511);
