INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今日もたくさん描きましたよ！\n壁に絵を描くのって大変かなって\n最初は思ってたんですけど……\n私、分かっちゃったんですよ！", 1, 23312, 0, 11, 23312009, 101111);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 23312, "", 91, 23312010, 0);
