INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "手を動かしながら考えて\n色んな人と協力する所もあったりして\nこれってお裁縫と似てるんです！\nすごいですよね、お兄ちゃん！", 1, 23312, 0, 11, 23312012, 101111);
