INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "権能、解放。\nオブジェクト……\nなぁんてね、ウソウソ。\nちゃんと自分の手で仕上げたよ。", 1, 23412, 0, 11, 23412009, 106811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 23412, "", 91, 23412010, 0);
