INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "七冠なんて呼ばれていようと、\nみんなで描いているこの壁画の前では\n皆同じだからね。\nペンキに塗れて、楽しんでるさ。", 1, 23412, 0, 11, 23412012, 106811);
