INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よし、任務完了だ！\n……と、威勢よく言ってみたはいいが、\n絵を描いてばかりで、いざという時に\n本分が果たせるのだろうか……", 1, 23512, 0, 11, 23512009, 105311);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 23512, "", 91, 23512010, 0);
