INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "このままでは軍人としての\n勘も鈍ってしまう！　今すぐ帰って、\nギルドの仲間たちと訓練の続きだ！", 1, 23512, 0, 11, 23512012, 105311);
