INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うーん……なんと言いますか。\n絵を描くのは楽しいんですけど、\nちょっと刺激が足りないというか……", 1, 23612, 0, 11, 23612009, 104511);
