INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "壁を見ていて思い出しマシタ。\n確か忍術に、壁と一体になって\n敵をやり過ごす極意があったと\n思いマス。", 1, 23712, 0, 11, 23712009, 103011);
