INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "絶対に違うと思います……\n二人とも、自分の好きなものに\n忠実なだけというか……", 1, 23812, 0, 11, 23812041, 105511);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 23812, "", 91, 23812042, 0);
