INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ほら、いつまでも壁の前で\nダラダラしてないで帰るぞ！\n私たちに必要なのは、尊さだの\n芸術だのではなく、訓練なんだからな！", 1, 23812, 0, 11, 23812046, 105311);
