INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うむ、素晴らしい仕上がりだ。\n何度も引き受けたかいあって、\n畑違いの仕事にも関わらず、\nすっかり絵描きが板についてしまった。", 1, 24812, 0, 11, 24812009, 105311);
