INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "もしかして、軍人よりこっちの方が\n向いているのでは……はっ！\nいかん、いかん！　私は誇り高き\n軍人だ！　軍人なのだ～……", 1, 24812, 0, 11, 24812013, 105311);
