INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "こ、このお仕事もだいぶ慣れて\nきたので、最近はクウカも\nよりこだわって作業するように\nしてるんですよ……？", 1, 24912, 0, 11, 24912009, 104511);
