INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ホントにランドソルって広いッスよね～\nみんなで壁に絵を描いてるはずなのに、\nまだまだ終わりが見えないッス。", 1, 25512, 0, 11, 25512009, 100511);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 25512, "", 91, 25512010, 0);
