INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "いつかこの事業が終わったら、\nたくさんの絵が見渡す限り\n描かれてるってことッスね。\n完成形が、今から楽しみッス♪", 1, 25512, 0, 11, 25512012, 100511);
