INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "また一つ、かわいいボクに\nよって美しい芸術が完成\nしてしまったよ……天はボクに、\nいくつ才能を与えるつもりなのかな？", 1, 25712, 0, 11, 25712009, 100811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 25712, "", 91, 25712010, 0);
