INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "けれど、悩ましい才能だよね。\nボクのかわいさと、描いた絵の美しさが\n競い合うようなことになったら……\nまぁ、ボクの方がかわいいよね♪", 1, 25712, 0, 11, 25712013, 100811);
