INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "実は、ちょっとだけ\nフラフラ～ってしてます……\nみんなでお絵描きするのが楽しくて、\nはしゃぎすぎちゃったみたいで……", 1, 26212, 0, 11, 26212032, 103811);
