INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "あ、だったら、リマの背中を借りたら？\n今日は天気もいいし、いい感じに\nふわふわで最高だったよ～", 1, 26212, 0, 11, 26212037, 102611);
