INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "せやねぇ♪\nみんなでわいわいしながら、\nまったりと描くんも楽しかったわぁ♪\n絵にもそれが表れてます♪", 1, 26222, 0, 11, 26222027, 101011);
