INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "でーじ分かるさ～！\n見てるとこう、ワクワクしてきて\n思わず踊りたくなるね～\nよ～し、マコトも一緒に踊るさ～♪", 1, 26222, 0, 11, 26222032, 101711);
