INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "え、あたしも踊るのかよっ！？\nていうか、さっきも踊ってただろっ？\nあ、あんまり引っ張るなって！", 1, 26222, 0, 11, 26222037, 104311);
