INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そんなことない！　バッチリだよ！\nやっぱりグレアは天才かも！\nアートの申し子で間違いない！\nルゥもそう思うでしょ！", 1, 26232, 0, 11, 26232023, 109211);
