INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ルゥの中にいるルゥも言ってます！\nグレアせんぱいは天才で、申し子です！\nルゥがラクガキの女王なら\nせんぱいはラクガキのゴッドです！", 1, 26232, 0, 11, 26232028, 109311);
