INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よいしょーっと！\nこんなところかしら？\nついかわいくない声が出ちゃったけど、\n絵はかわいく描けたわ♪", 1, 26412, 0, 11, 26412009, 105211);
