INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今回はなまらいい感じに描けたべや！\n絵はあんま描かねぇから苦労したけんど\nこれならその甲斐もあるってもんだべ♪", 1, 26512, 0, 11, 26512009, 103311);
