INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "やっぱり踊って歌いながら絵を描くのは\nでーじ楽しいさ～♪\nもっと踊って……え？\n絵の具がはねちゃってる～？", 1, 26612, 0, 11, 26612009, 101711);
