INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うーん、上達してきた気もするけど、\nまだまだって感じだなぁ……\n他のやつはどんな絵を描いてるんだ？\nどれどれ、ちょっと見せてもらうか。", 1, 26712, 0, 11, 26712009, 104311);
