INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "でもぉ～？　ら～いじょ～ぶれ～～す！\n麦しゅわがあればぁ、描けるのれす！\nらから～……ご褒美にもういっぱ～い♪\nじゃんじゃんいっくわよ～～！！", 1, 27212, 0, 11, 27212012, 103411);
