INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "やはりこの姿だと、作業しやすいのう！\nふふっ、これもお主のおかげじゃな。\nどれ、少しなら褒美をやっても良いぞ？\nなに……絵を見れるだけで十分じゃと？", 1, 27312, 0, 11, 27312009, 104411);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 27312, "", 91, 27312010, 0);
