INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "確かにわらわの描いた絵には\nその価値があるとは思うが……\nもう少し、こう……褒美らしいものでも\n良いのだぞ？　本当に良いのか？", 1, 27312, 0, 11, 27312013, 104411);
