INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今日もプリンのために、描いたの♪\nミヤコ、もう何回も描いたから\nこんなに上手になったの～♪", 1, 27412, 0, 11, 27412009, 100711);
