INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふっ、頬についた絵の具すら、\nボクを魅力的に見せちゃうね♪\nそれどころか、何か新しいメイクの\n参考になるかもしれないよ♪", 1, 27612, 0, 11, 27612009, 100811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 27612, "", 91, 27612010, 0);
