INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "これは帰ったら早速試して……\nえ？　そのままでいいって？\n確かにその通りだね！\nさすがキミ、ボクの美を理解してるよ♪", 1, 27612, 0, 11, 27612012, 100811);
