INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今回も滞りなく、任務完了だ！\n絵の仕上がりも上々だし、これならば\n問題は……む、なんだ。\n貴公よ、何か言いたそうだな？", 1, 27712, 0, 11, 27712009, 105311);
