INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "おぉー、クウカがひいた曲線、\nすごくきれいデス！\nまるでウキヨエマスターみたいデスね！\nワタシにもその技、教えてクダサイ！", 1, 27812, 0, 11, 27812031, 103011);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 27812, "", 91, 27812032, 0);
