INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うむ……もはや、何も言うまい。\nしかし共同作戦というのは悪くないな。\nこれはチームプレイの\n良い訓練になるぞ！", 1, 27812, 0, 11, 27812041, 105311);
