INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふっ、ボクが一番\n輝いちゃって申し訳ないけどね♪\n流れる汗も太陽に照らされて、\nボクを彩ってるみたいじゃないか♪", 1, 27812, 0, 11, 27812046, 100811);
