INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今日はここまでっと。\nちゃんと道具の手入れもしたから、\n絵の具のノリが良かったかな。\nいい線が描けた気がするよ♪", 1, 28212, 0, 11, 28212009, 103711);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 28212, "", 91, 28212010, 0);
