INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "さてと、それじゃあ他の絵を眺めながら\n見回りをしてこよう。\nこんな平和な日々を守る為に\n仕事も頑張らないと♪", 1, 28212, 0, 11, 28212012, 103711);
