INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うん、依頼された部分は描けたかな。\nランドソルを守るだけではなく、\nこういう任務も大事だよね。\n上手に描けているといいんだけど。", 1, 28312, 0, 11, 28312009, 104711);
