INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "実は、団員からもっと息抜きを\n覚えた方がいいと言われてね。\nキャンプをしながら、\n風景画を楽しむというのも良さそうだ。", 1, 28312, 0, 11, 28312012, 104711);
