INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふーむ……描けば描くほど、\n新しいイメージが湧いてきて困るな☆\n次はもう少し考えてから、\nやってみるか？", 1, 28512, 0, 11, 28512009, 107111);
