INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふんっ！　くだらんな！\n血湧き肉躍る命の駆け引きのように\n荒々しく筆を振るう！　それこそ芸術！\n坊やもそう思うだろう？", 1, 28512, 0, 11, 28512012, 107111);
