INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "うん、最近やったゲームのおかげで\nきれいに描けたわ。\nまさか遊んでただけなのに、\nこんな形で役に立つなんてね♪", 1, 28812, 0, 11, 28812009, 102211);
