INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "これだけ描けてれば、\nアカリに見せても大丈夫よね！\nそうだ、アカリも描くみたいだし、\nゲームのこと教えてあげよっと♪", 1, 28812, 0, 11, 28812012, 102211);
