INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふ……\nアンはなんでも楽しそうにやるけどね。\n一緒にいる私まで楽しくなるよ……", 1, 29012, 0, 11, 29012023, 109411);
