INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "こんな感じでいいのかな～？\n何回かこのお仕事してるけど、いっつも\n物足りなく感じちゃうんですよね。\nもう少しかわいい雰囲気にしたいな～", 1, 29312, 0, 11, 29312009, 100611);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 29312, "", 91, 29312010, 0);
