INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "よいしょ……っと！\nふぅ……絵を描くのって、\nこんなに体力がいる作業なのね。\nアカリは楽々こなしてたみたいだけど。", 1, 29412, 0, 11, 29412009, 102211);
