INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "こうした作業は、慣れてくると\n捻ったことがしたくなるもの……\nわらわも、もう少し凝った表現に\n挑戦してみるかのう。", 1, 29512, 0, 11, 29512009, 104411);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 29512, "", 91, 29512010, 0);
