INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "もう少し前衛的かつ、抽象的なタッチで\n人間を描いてみるなどどうじゃ？\n……この壁画はそういう路線ではない？\nふむ、芸術も難儀なものじゃな。", 1, 29512, 0, 11, 29512012, 104411);
