INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ずーっとお絵描きしてるけど、いつも\n同じ数のプリンしかもらえないの～……\n絶対、まだあるのに隠してるの～！\nケチくさいの～！", 1, 29612, 0, 11, 29612009, 100711);
