INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "さて、こんなものかしらね？\n普段子どもたちのお絵描きを\n見ているせいかもしれないけど、\nなんだか童心に帰った気分だわ。", 1, 30012, 0, 11, 30012009, 102811);
