INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ここを、こうして……うん。\n今回はこんなもんかしらねー？\n慣れてきたおかげか、\n結構あっさり終わったわ。", 1, 30412, 0, 11, 30412009, 106011);
