INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "本日の作業は、完了でございます。\nわたくしもすっかり慣れたもので、\n今ならば目を閉じながらでも\n思うがままに描けそうです。", 1, 30512, 0, 11, 30512009, 105911);
