INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "お絵描き、ずーっと続けてたから、\nかなり上達してきた気がするわね～♪\n使う道具についても、いろいろと\nお勉強になったし。", 1, 30712, 0, 11, 30712009, 101511);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 30712, "", 91, 30712010, 0);
