INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "また、コツとか教えてあげるわね。\nこの調子で一緒にお絵描きを続ければ、\nあなたの心もますます豊かになるわ～\n子どもの情操教育にいいって聞くし♪", 1, 30712, 0, 11, 30712012, 101511);
