INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "壁にみんなで絵を描く、か……\nえっと、これってボードゲームの\nネタにならないかなーって思ったの。", 1, 30812, 0, 11, 30812009, 102211);
