INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "売られてる物で遊ぶのもいいけど、\n自作したゲームで遊ぶのも\nまた違った楽しみがあるのよ？\n今度、一緒に挑戦してみない？", 1, 30812, 0, 11, 30812012, 102211);
