INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "最近、もうすっかりお絵描きに\nハマっちゃいました～♪\n筆とか絵の具とかも自分で買って、\nおうちでもお絵描きしてるんですよ？", 1, 30912, 0, 11, 30912009, 100611);
