INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "それで、お姉ちゃんの似顔絵を\n描いたんですけど……なんか、誰にも\n見せちゃダメって怒られちゃって。\nかわいいポーズで描いたのにな～", 1, 30912, 0, 11, 30912013, 100611);
