INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "趣味とか好きなお店とか同じで、\n辛いときには無限に励ましてくれて、\n夜はパジャマパーティーとかも……！\n今から続き、描こうかな……？", 1, 31412, 0, 11, 31412012, 104011);
