INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "……本当に、素敵な壁画だわ。\n誰か一人だけで描いたんじゃなく、\nたくさんの人たちが筆をとって、\nここまで描き続けたんですものね。", 1, 31612, 0, 11, 31612009, 106411);
