INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "この壁も、いい感じに\n仕上がってきましたね～♪\nちょくちょく皆さんの個性が光ってて、\nザ・ランドソルって感じがやばいです☆", 1, 32012, 0, 11, 32012012, 105811);
