INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "……王女としても、やっぱり\nいろんな考えの人たちが、みんな\n幸せに暮らせる場所にしたいんですよ。\nこれが、その象徴になるといいですね♪", 1, 32012, 0, 11, 32012015, 105811);
