INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "毎度思うんだけどさ～\nこう、一気にちゃちゃっと\n壁に絵を自動で描いてくれる\n魔法とかないの？", 1, 32112, 0, 11, 32112022, 102611);
