INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "【牧場（エリザベスパーク）】には、\nそんな高度な魔法を扱える人が\nいないので……お姉ちゃんなら\nできるかもしれないですけど。", 1, 32112, 0, 11, 32112027, 103811);
