INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "う～ん……\nとりあえず絵は完成したけど、\nなんか大人っぽさが\n足りない気がするのよね……", 1, 32312, 0, 11, 32312018, 105011);
