INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今回は、つらら状に凍らせたペンキを\n使って絵を描いてみたの。\nペンと同じように使えるから、\n細かい線を描くのに便利だと思って。", 1, 32412, 0, 11, 32412009, 106411);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 32412, "", 91, 32412010, 0);
