INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はい、おしまい！\n今回も女の子らしくかわいい絵に\n仕上がったと思うんだけれど、\n感想はどうかしら？", 1, 32812, 0, 11, 32812009, 105211);
