INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふふっ、ありがとう♪\n自分の作った物を褒めてもらうと、\nやっぱりうれしくなるわね。\n次もかわいい絵になるよう、頑張るわ♪", 1, 32812, 0, 11, 32812012, 105211);
