INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふぅ……お絵描きのお仕事は\n体力がいるので大変ですが、\n自分のペースで進められるのは\nありがたいですね。", 1, 32912, 0, 11, 32912009, 103811);
