INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ふぅ……\n絵を描くのに体を動かしたせいか、\nちと喉が渇いたのう。\nなにか飲み物を持っておらんか？", 1, 33512, 0, 11, 33512009, 104411);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 33512, "", 91, 33512010, 0);
