INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ん？　なぜ赤いペンキを差し出す？\n……もしやお主、赤い液体であれば\nなんでも構わぬと思っておらんか？\nせめて、人間でも飲めるもので頼む。", 1, 33512, 0, 11, 33512012, 104411);
