INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "大勢で絵を描く、という試みは\n素晴らしいものなのですが、参加者に\n女性が多いのは困りものですね。\n主に、父が原因なのですが。", 1, 33612, 0, 11, 33612009, 103111);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 33612, "", 91, 33612010, 0);
