INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "もう何度父がナンパした他のギルドの\n方々に頭を下げたか分かりません……\n次にやったらペンキ缶に沈めると\n伝えてからは、大人しくなりましたが。", 1, 33612, 0, 11, 33612012, 103111);
