INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "……この仕事って、気を付けないと\n服が塗料で汚れちゃうのが困るわね。\n昨日はアカリが思いっきり汚してきて、\nお説教する羽目になったし。", 1, 33812, 0, 11, 33812009, 102211);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 33812, "", 91, 33812010, 0);
