INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そう、お説教したばっかりなのよ……\nなのに、今日に限って私もスカートに\n思いっきりペンキが跳ねるなんて！\nあの子になんて言い訳するのよ～！？", 1, 33812, 0, 11, 33812012, 102211);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 33812, "", 91, 33812013, 0);
