INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ちょっとアンタ！\n手が絵の具で汚れちゃってるじゃない、\nきれいに洗ってから帰らないとダメよ？", 1, 33912, 0, 11, 33912009, 105011);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 33912, "", 91, 33912010, 0);
