INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "身だしなみがだらしないと、\nレディに相応しい男の子になれないわ。\n石鹸を取ってきてあげるから、\nそこで待ってなさい。", 1, 33912, 0, 11, 33912012, 105011);
