INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "慣れって怖いよね～\n最初は壁に絵を描くなんて\nめんどくさい仕事、絶対お断り\nって思ってたんだけどさ。", 1, 34012, 0, 11, 34012009, 102611);
