INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "こういう、でっけぇ絵を眺めてると、\n心が洗われるような気分になるべな～\nなんだか、爽やかな傑作ギャグを\n思いつけそうな気がしてきたべ！", 1, 34112, 0, 11, 34112009, 103311);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34112, "", 91, 34112010, 0);
