INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ちょっと待ってろ～、う～ん……うん！\nみんなで描いた絵は、\nやっぱり「絵」えな～！\n……今のは取り消しだべ。", 1, 34112, 0, 11, 34112012, 103311);
