INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ん？　私がどうやって\n筆を持ってるのか気になってるって？\nずいぶん今さらな質問ね～", 1, 34212, 0, 11, 34212009, 105211);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34212, "", 91, 34212010, 0);
