INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "剣を持っているときと同じよ。\nほら、こんなふうに持ってるの。\n……わ、分からない？\nほら、だからこうよ！　こうだって！", 1, 34212, 0, 11, 34212012, 105211);
