INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "できたの～！\n今回もよく描けたから、\n当然の権利としてプリンを\n要求するの、早く出せなの。", 1, 34312, 0, 11, 34312026, 100711);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34312, "", 91, 34312027, 0);
