INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 0, "", 0, "vo_wac_230123_001", "", 34312, "", 21, 34312030, "vo_wac_230123");
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "……困りましたね。\n今日はもうミヤコさんに渡せるプリンが\nありませんが、どうしましょう？", 1, 34312, 0, 11, 34312031, 103111);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34312, "", 91, 34312032, 0);
