INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "似たようなもので満足\nしてくれないかなぁ？\n茶碗蒸しとか♪", 1, 34312, 0, 11, 34312036, 100611);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34312, "", 91, 34312037, 0);
