INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "色合いと食感が似てるだけで、\n味は全然別物じゃない……\nババロアとか、ゼリーとかの方が\nまだ見込みがあるんじゃない？", 1, 34312, 0, 11, 34312041, 102211);
