INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "無駄じゃ、ちゃんとしたプリン以外で\nこやつが満足するものか。\nなんとか待たせて、\n手作りするほかないのう。", 1, 34312, 0, 11, 34312046, 104411);
