INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "絵を描くのも慣れましたけど、おかげで\n最近マンネリ気味なんですよね。\nなにか美しいものを思い浮かべつつ、\n解決策を検討しましょう。", 1, 34612, 0, 11, 34612009, 105411);
