INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "最近、スズナちゃんやミサキちゃんが\n絵画についていろいろと\nお勉強をしているみたいなの。\n素敵な絵が描けるようになりたいって。", 1, 34712, 0, 11, 34712009, 101811);
