INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "できた～！\n今回もかなりエモい感じに\n描けたと思うんだけど、\nヒデサイはどう思う？", 1, 34812, 0, 11, 34812009, 101611);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34812, "", 91, 34812010, 0);
