INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そういえば、騎士クンも\nすごく絵を描くのが上手になったよね。\nさ、最初の頃は下手だったとか、\nそういうことじゃないよ？", 1, 34912, 0, 11, 34912009, 100211);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 34912, "", 91, 34912010, 0);
