INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "なんていうか……\n絵から、あなたの温かさが\n伝わるようになってきた気がするの。\n二人で描いたからかもしれないけどね♪", 1, 34912, 0, 11, 34912012, 100211);
