INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "絵を描くときは、静かな湖に\n釣り糸を垂らす時のように、\n穏やかな心持ちであるべきだ。", 1, 35012, 0, 11, 35012009, 100311);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 35012, "", 91, 35012010, 0);
