INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "慌てて激しく筆を動かしたり、\n上手くいかなかったからって\n気持ちを逆立ててはいけない。\n絵を見た人にも分かってしまうからね。", 1, 35012, 0, 11, 35012012, 100311);
