INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "お絵描きするときはお筆をつかうけど、\n白いふさふさのところってどうやって\n作ってるのかな……？\nえっ、どうぶつさんの毛なの？", 1, 35212, 0, 11, 35212009, 102011);
