INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "えへへ～、おわり～！\nふつう壁に絵を描いたら怒られるのに、\n逆に褒めてもらえるって不思議かも？", 1, 35412, 0, 11, 35412009, 100411);
