INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ミソギがちっちゃいころ、家の壁に\n絵を描いたらすごく怒られたもん。\nどっちも壁に絵を描いてるのにな～\n大人のひとの考えって、わかんないよ～", 1, 35412, 0, 11, 35412012, 100411);
