INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "色には見た人の気分を\n変化させる効果があるというけど……\n確かに色鮮やかな壁を見ていると、\n楽しい気分になってくるね。", 1, 35912, 0, 11, 35912009, 104711);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 35912, "", 91, 35912010, 0);
