INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "私の鎧も、このようにカラフルで\nかわいげのある塗装を試してみようか。\n団員たちの士気もあがるかもしれない。\n……やめた方がいい？　そうかな？", 1, 35912, 0, 11, 35912012, 104711);
