INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "こういう作業って慣れてくると、\nオリジナリティーを出してみたく\nなったりしない？\nこっそり魔法少女要素を足すとか。", 1, 36012, 0, 11, 36012009, 103711);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 36012, "", 91, 36012010, 0);
