INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "あはは、大丈夫、本当にはやらないよ。\nでも、魔法少女の絵は描きたいなぁ……\nいっそ漫画に……うんうん、次々と\nアイデアが浮かんできたよ。", 1, 36012, 0, 11, 36012012, 103711);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 36012, "", 91, 36012013, 0);
