INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "へぁ～……ひぃ～……\nや、やっと描き直しが終わったッス……\nクリスティーナおばさんのチェック、\nいくらなんでも厳しすぎるッスよ～……", 1, 36112, 0, 11, 36112009, 100511);
