INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "さて、ワタシの担当は終わったが……\n改めて、他の面子の仕事も\n確認させてもらおうではないか。\n手落ちがあってはいかんからな。", 1, 36712, 0, 11, 36712009, 107111);
