INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "なんとなく、ではございますが。\nみなさま指示書に従って絵を\n描いているはずなのに、\nどことなく個性が感じられますね。", 1, 37112, 0, 11, 37112009, 105911);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 37112, "", 91, 37112010, 0);
