INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "恐らくここはぺコリーヌさま、\nあちらはキャルさまで、そこは主さま、\nこの辺りはシェフィさまでしょう。\n大変、上手に描けておりますよ。", 1, 37112, 0, 11, 37112012, 105911);
