INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "たくさんの絵を描いてきたッスけど、\n自分、ここまでこの仕事が長続き\nするとは、正直思ってなかったッス。", 1, 37412, 0, 11, 37412009, 100511);
