INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "その……自分はこういう作業、\n向いてないと思ってたッスから。\nきっといろんな人と一緒だったから、\nがんばってこれた気がするッス♪", 1, 37412, 0, 11, 37412012, 100511);
