INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "さて、そろそろ切り上げようか。\n……うん、たくさんの絵が集まって、\nとっても素敵な壁になった。\n心から、そう思っているよ。", 1, 37512, 0, 11, 37512009, 104711);
