INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "ハ？　先輩、いまなんて言いました？\nこの城壁お絵かきプロジェクトに、\nカルミナちゃんたちも参加してる？\n三人ともうっかり壁にサイン書いてた？", 1, 37712, 0, 11, 37712009, 110911);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 37712, "", 91, 37712010, 0);
