INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "あのさあ……カルミナ創作小話は\nチエルもよく匿名で投稿しますけども、\n現実に反したお馬鹿キャラみたいな\n解釈広めるのはやめましょうよ。ね？", 1, 37712, 0, 11, 37712012, 110911);
