INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "おし、どーよコレ……知んないけど、\n今日はよく出来たんじゃないの。\n記念に転写魔法器で自撮りしとくか、\nつって……", 1, 37812, 0, 11, 37812009, 110811);
