INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "おい諸君、大変だ。\n国家予算こと我々の労働報酬について\nギルド管理協会に問い合わせたところ、\nそんなもん出ねえ的な回答があった。", 1, 37912, 0, 11, 37912021, 111011);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 37912, "", 91, 37912022, 0);
