INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0.2, "wac_talk_smile_loop_L", "", 0, "wac_talk_smile_in_L", 1, 37912, "", 3, 37912024, 110911);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", 0, "", 0, "vo_wac_230228_001", "", 37912, "", 21, 37912025, "vo_wac_230228");
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "またまた～！　そんなのアレですよ、\nそう言われてうちらがワーワー騒いでる\nところに、後ろからカリンねえさんが\nプラカード持って出てくるやつですよ。", 1, 37912, 0, 11, 37912026, 110911);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 37912, "", 91, 37912027, 0);
