INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "「ドッキリ大成功です！」つってね。\nプラカードと国家予算持ってね。\nあるある、絶対ソレだわ。", 1, 37912, 0, 11, 37912031, 110811);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 37912, "", 91, 37912032, 0);
