INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "今回も上手にできたにゃ～♪\nあたしたちも気づけばすっかり\n絵描きの風格になったにゃ。\nこれで新しい商売でも始めるにゃ？", 1, 38012, 0, 11, 38012022, 104611);
