INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "商売って……描いた絵を売るとか？\nうーん、別に芸術家として\n有名になったわけでもないし、\nちょっと難しいような……", 1, 38012, 0, 11, 38012027, 104811);
