INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "麦しゅわ！　麦しゅわの絵を描くの！\nそれをね～、酒場とかに売って～……\nそのお金で、麦しゅわを買うの～♪\n……ひっく。", 1, 38012, 0, 11, 38012032, 103411);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 38012, "", 91, 38012033, 0);
