INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "業務終了と同時に麦しゅわをあおることの\n是非はさておき、それは名案ですわ！\n今回のノウハウを活かして、商店向けの\n看板制作にチャレンジいたしましょう！", 1, 38012, 0, 11, 38012037, 103211);
