INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "みんなで、がんばって\n描き続けてきましたから……\n最後まで、丁寧にお仕事を\nしたいですね♪", 1, 38212, 0, 11, 38212027, 103811);
