INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "しおりんは真面目だねぇ～……\nあたしはもう十分働いたから、\n残りは他のみんなに託すことにするよ。", 1, 38212, 0, 11, 38212032, 102611);
