INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "この作業も長くやってきたってのに、\n結局考えてることはバラバラだねぇ……\nそれでも上手いこと回っていくのが、\nウチのギルドのよさなんだけどさ。", 1, 38612, 0, 11, 38612046, 105611);
