INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "もうすっかり絵を描くのにも\n慣れっこだけど、最近は\nちょっと欲も出てきてね……", 1, 38712, 0, 11, 38712009, 105611);
