INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "絵を描くと一口に言っても、\n様々な工程がありますが……\nあなた様は、どの作業が\n一番楽しいと感じますか？", 1, 38812, 0, 11, 38812009, 102711);
