INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "私は、やはり色を塗るときが\n最も充実していると感じますわ……\n自分の色で、相手を染め上げる瞬間が\nたまらないのです……クスクス♪", 1, 38812, 0, 11, 38812013, 102711);
