INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "はい、おわり～\nいやいや、我ながらがんばったでしょ？\nあたしがこんなに長時間働くだなんて、\n世界滅亡の前触れかもよ。", 1, 39812, 0, 11, 39812009, 102611);
