INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "どんな伝説にも、終わりがある……\nシグルドよ、我らの運命を\n堅牢なる防壁に刻む作業も、\n終幕までわずかのようだ。", 1, 39912, 0, 11, 39912009, 100911);
