INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "……あなた様と共に絵を描く時間も、\nそろそろ終わってしまうのですね。\nとても、名残惜しい気分ですわ……", 1, 40112, 0, 11, 40112009, 102711);
