INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "……というわけで！\nカリンさん、お待たせしました。\nランドソルの景観向上事業、\n全力全開でやり遂げましたよ☆", 1, 40922, 0, 11, 40922004, 105811);
