INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "みなさん、本当にお疲れさまでした！\nこれだけ大きな壁に絵を描くのは\n大変だったと思いますが、\nとても鮮やかな景観になりましたよ♪", 1, 40922, 0, 11, 40922009, 118511);
INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES ("", "", "", "", "", "", 40922, "", 91, 40922010, 0);
