INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そうでございますね。\n【美食殿】だけでなく、多くのギルドの\nみなさまが力を合わせた結果、\n美しい壁になったのだと思います。", 1, 40922, 0, 11, 40922014, 105911);
