INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "私たち自身にとっても、\n素敵な思い出になったと思うわ。\nこうして形に残るお仕事なら、また\nいつか……見に来ることもできるし。", 1, 40922, 0, 11, 40922019, 106411);
