INSERT INTO `v1_b8c2e5696089311a5f417cd9b6a7fd39e095edfb14066a0f7d4ded1cac648a1b` VALUES (0, 1, 0.5, 10, "そんなこと言って、キャルちゃんも\nノリノリで描いてたじゃないですか♪\n絵の才能があるかもーって\nみんなに自慢もしてましたし。", 1, 40922, 0, 11, 40922030, 105811);
